  phone?: string
  category?: 'shop' | 'vet' | 'groomer' | 'shelter' | 'cafe' | 'boarding'
  opensAt?: string
  closesAt?: string
  website?: string
  categories?: string[]
  description?: string
  image?: string
  /** Extra real photos of this shop, for the detail gallery. */
